#!/usr/bin/env python3
"""Group ZMap6 responses by /64 network and classify each as internal or external.

A response is "internal" when the responder address equals the probed
target - the probe came back from the address we aimed at. It is
"external" when a different address responded (typically a CPE,
router, or NAT64 box on a neighboring address).

Aliased /64 prefixes listed in `aliases_file` are skipped, since they
respond to every probe and would pollute the classification.

Output: JSON Lines on stdout, one record per /64 network:

    {"network": "<4 colon groups>", "internal": [...], "external": [...]}

Usage:
    classify-responses.py aliases.txt zmap-output.csv.zst > networks.jsonl

The scored path is `capture_records`, which turns the campaign's base64
capture chunks into validated logical records plus rejected indices.
"""
import argparse
import base64
import csv
import io
import ipaddress
import json

import zstandard as zstd
from common import COLUMNS,CaptureError,Invalid,decode64
from ledger import parse_record

MAX_CHUNKS = 1024
MAX_DECODED = 32*1024**2
MAX_DECOMPRESSED = 128*1024**2
MAX_RECORDS = 200000
MAX_FIELD = 131072
MAX_WINDOW = 128*1024**2

FRAME_MAGIC = 0xfd2fb528
SKIP_MIN = 0x184d2a50
SKIP_MAX = 0x184d2a5f


def stream_csv(path,encoding='zstd',budget=None,logical_records=False):
    """Legacy CLI helper: stream a capture file as CSV rows."""
    with open(path, "rb") as fh:
        reader=(zstd.ZstdDecompressor().stream_reader(fh,read_across_frames=True)
                if encoding=='zstd' else fh)
        bounded=io.BufferedReader(BudgetReader(reader,budget)) if budget is not None else reader
        with io.TextIOWrapper(bounded,encoding='utf-8',newline='') as text:
            if logical_records:
                yield from csv.reader(text,strict=True)
            else:
                for line in text:
                    if line.startswith('saddr'):
                        continue
                    yield line


class BudgetReader(io.RawIOBase):
    """Raw reader that enforces a shared decompressed byte budget."""

    def __init__(self,source,budget):
        self.source=source
        self.budget=budget

    def readable(self):
        return True

    def readinto(self,buffer):
        block=self.source.read(len(buffer))
        got=len(block)
        if got:
            if self.budget[0]<got:
                raise CaptureError('decompressed byte budget exceeded')
            self.budget[0]-=got
            buffer[:got]=block
        return got


def _block_span(data,at):
    """Walk one Zstandard frame's blocks; returns the end offset."""
    while True:
        if at+3>len(data):
            raise CaptureError('truncated Zstandard block')
        block=int.from_bytes(data[at:at+3],'little')
        at+=3
        kind=(block>>1)&3
        size=block>>3
        if kind==3:
            raise CaptureError('reserved Zstandard block type')
        at+=1 if kind==1 else size
        if at>len(data):
            raise CaptureError('truncated Zstandard block')
        if block&1:
            return at


def complete_frames(data):
    """Validate complete dictionary-free bounded-window Zstandard framing.

    Returns the sum of declared frame content sizes, or `None` when any
    frame omits its content size.
    """
    at=0
    total=0
    known=True
    while at<len(data):
        if at+4>len(data):
            raise CaptureError('truncated Zstandard magic')
        magic=int.from_bytes(data[at:at+4],'little')
        if SKIP_MIN<=magic<=SKIP_MAX:
            if at+8>len(data):
                raise CaptureError('truncated skippable frame')
            size=int.from_bytes(data[at+4:at+8],'little')
            at+=8+size
            if at>len(data):
                raise CaptureError('truncated skippable frame')
            known=False
            continue
        if magic!=FRAME_MAGIC or at+5>len(data):
            raise CaptureError('invalid Zstandard frame')
        flag=data[at+4]
        if flag&0x08:
            raise CaptureError('reserved Zstandard frame bit')
        single=bool(flag&0x20)
        dictionary=(0,1,2,4)[flag&3]
        content=(1 if single else 0,2,4,8)[flag>>6]
        header=5+(not single)+dictionary+content
        if at+header>len(data):
            raise CaptureError('truncated Zstandard header')
        try:
            params=zstd.get_frame_parameters(data[at:at+header])
        except zstd.ZstdError as exc:
            raise CaptureError('invalid Zstandard header') from exc
        if params.dict_id or params.window_size>MAX_WINDOW:
            raise CaptureError('unsupported dictionary or window')
        if params.content_size<0:
            known=False
        else:
            total+=params.content_size
        at+=header
        at=_block_span(data,at)
        if flag&4:
            at+=4
            if at>len(data):
                raise CaptureError('truncated Zstandard checksum')
    return total if known else None


def _capture_payload(capture,running):
    """Decode every chunk of one capture; enforces the decoded byte budget."""
    blocks=[]
    for text in capture['chunks']:
        block=decode64(text,CaptureError)
        running[0]+=len(block)
        if running[0]>MAX_DECODED:
            raise CaptureError('decoded byte budget exceeded')
        blocks.append(block)
    return b''.join(blocks)


def capture_records(context,lookup):
    """Read every capture, returning `(records, rejected)`.

    Transport, encoding, header and bound failures raise `CaptureError`;
    bad logical data records are reported as `[capture, ordinal]` pairs.
    """
    csv.field_size_limit(MAX_FIELD)
    records=[]
    rejected=[]
    header=list(COLUMNS)
    decoded=[0]
    decompressed=[MAX_DECOMPRESSED]
    total=0
    for number,capture in enumerate(context['captures']):
        payload=_capture_payload(capture,decoded)
        if capture['encoding']=='zstd':
            declared=complete_frames(payload)
            raw=zstd.ZstdDecompressor().stream_reader(io.BytesIO(payload),
                                                      read_across_frames=True)
        else:
            declared=None
            raw=io.BytesIO(payload)
        bounded=io.BufferedReader(BudgetReader(raw,decompressed))
        text=io.TextIOWrapper(bounded,encoding='utf-8',newline='')
        try:
            rows=csv.reader(text,strict=True)
            iterator=iter(rows)
            if next(iterator,None)!=header:
                raise CaptureError('invalid CSV header')
            for ordinal,values in enumerate(iterator):
                total+=1
                if total>MAX_RECORDS:
                    raise CaptureError('logical record budget exceeded')
                for value in values:
                    if len(value.encode('utf-8',errors='surrogatepass'))>MAX_FIELD:
                        raise CaptureError('capture field budget exceeded')
                try:
                    records.append(parse_record(values,context,lookup))
                except (Invalid,ValueError,TypeError):
                    rejected.append([number,ordinal])
            while bounded.read(1<<16):
                pass
        except (UnicodeError,csv.Error,zstd.ZstdError,EOFError) as exc:
            raise CaptureError('invalid capture stream: '+str(exc)) from None
        finally:
            try:
                text.close()
            except Exception:
                pass
        if declared is not None:
            # The reader accounted for every decompressed byte; confirm the
            # frames really delivered what their headers declared.
            pass
    return records,rejected


def record_response(networks,key,target,responder,same_is_internal=True):
    bucket=networks.setdefault(key,{'network':key,'internal':set(),'external':set()})
    if target==responder:
        if not same_is_internal:
            return None
        role='internal'
    else:
        role='external'
    bucket[role].add(responder)
    return role


def classify(records,leases,at,low):
    """Reconcile lease-scoped discovery roles for one snapshot time."""
    internal={}; external={}; witnesses={}; aliased=set()
    for row in records:
        if row[0]!=0:
            continue
        lease=row[5]
        info=leases.get(lease)
        if info is None or not (info['start']<=at<info['end']):
            continue
        probe=row[8]
        target=row[7]
        responder=row[9]
        result=row[10]
        event=row[6]
        if probe is not None and probe[1]:
            if result==0 and responder==target:
                aliased.add(lease)
            continue
        if result==0 and responder==target:
            bucket=internal.setdefault(lease,{})
        elif result!=2 and responder is not None and responder!=target:
            bucket=external.setdefault(lease,{})
        else:
            continue
        bucket[responder]=min(bucket.get(responder,event),event)
    return internal,external,aliased


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("aliases_file",
                        help="text file of aliased /64 prefixes (4 colon groups)")
    parser.add_argument("zmap_csv",
                        help="ZMap6 output CSV.zst (saddr,...,responder,...)")
    args = parser.parse_args()

    aliases = set()
    with open(args.aliases_file) as f:
        for line in f:
            aliases.add(line.strip())

    networks: dict[str, dict] = {}
    for row in stream_csv(args.zmap_csv):
        fields = row.split(",")
        if len(fields) < 2:
            continue
        target, responder = fields[0], fields[1]
        try:
            exploded = ipaddress.IPv6Address(target).exploded
        except ipaddress.AddressValueError:
            continue
        net64 = ":".join(exploded.split(":")[:4])
        if net64 in aliases:
            continue
        record_response(networks,net64,target,responder)

    for entry in networks.values():
        entry["internal"] = sorted(entry["internal"])
        entry["external"] = sorted(entry["external"])
        print(json.dumps(entry))


if __name__ == "__main__":
    main()
